
<style>
@import url('https://fonts.googleapis.com/css2?family=DM+Sans:wght@400;500;600;700&family=Manrope:wght@500;600;700;800&display=swap');
:root{--ink:#17243b;--muted:#718096;--navy:#101d35;--blue:#315ee8;--blue2:#244bc4;--line:#e7ecf3;--bg:#f4f7fb;--white:#fff;--green:#12805c;--red:#c2414b;--shadow:0 18px 50px rgba(24,42,75,.07)}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font:14px 'DM Sans',Arial,sans-serif;line-height:1.6}h1,h2,h3,h4{font-family:Manrope,'DM Sans',sans-serif;line-height:1.25;margin-top:0;color:var(--ink)}a{color:var(--blue);text-decoration:none}a:hover{color:var(--blue2)}button,.btn{font:600 14px 'DM Sans',sans-serif;cursor:pointer;border:0;border-radius:9px;padding:12px 17px;background:var(--blue);color:#fff;display:inline-flex;align-items:center;justify-content:center;gap:8px;transition:.2s}button:hover,.btn:hover{background:var(--blue2);color:#fff;transform:translateY(-1px)}.btn-light{background:#edf2ff;color:#244bc4}.btn-light:hover{background:#dfe8ff;color:#193da9}.btn-danger{background:#fff1f1;color:#b42332}.btn-danger:hover{background:#ffe0e0;color:#8f1724}
input,select,textarea{width:100%;border:1px solid #dce3ed;background:#fff;border-radius:9px;padding:12px 13px;font:14px 'DM Sans',sans-serif;color:var(--ink);outline:none;transition:border .2s,box-shadow .2s}input:focus,select:focus,textarea:focus{border-color:#7595f5;box-shadow:0 0 0 3px rgba(49,94,232,.1)}textarea{min-height:120px;resize:vertical}label{display:block;font-weight:600;font-size:13px;margin:0 0 7px}.field{margin:0 0 18px}.muted,.subtle{color:var(--muted)}.eyebrow{text-transform:uppercase;letter-spacing:1.5px;color:#7186ad;font-size:11px;font-weight:700}.panel,.card{background:#fff;border:1px solid var(--line);border-radius:15px;box-shadow:0 5px 20px rgba(25,44,77,.025)}.panel{padding:25px}.alert{padding:13px 15px;border-radius:10px;background:#eaf8f1;color:#126b4b;margin:0 0 18px}.errors{padding:13px 16px;border-radius:10px;background:#fff0f0;color:#a52a35;margin:0 0 18px}.errors p{margin:3px 0}.pill{display:inline-flex;padding:5px 10px;border-radius:30px;font-size:11px;font-weight:700;background:#edf2ff;color:#3156c9}.pill.green{background:#e8f7ef;color:#13734f}.pill.orange{background:#fff3e4;color:#9a5a13}.pill.red{background:#ffeded;color:#b42332}
.shell{display:flex;min-height:100vh}.sidebar{width:252px;background:linear-gradient(180deg,#111f3a,#172b4d);color:#dce6f7;padding:27px 18px;display:flex;flex-direction:column;flex-shrink:0}.brand{font:800 19px Manrope,sans-serif;color:#fff;padding:0 12px 25px;border-bottom:1px solid #30415f}.brand small{display:block;font:500 11px 'DM Sans',sans-serif;color:#9fb1d0;letter-spacing:1.2px;text-transform:uppercase;margin-top:5px}.nav-caption{font-size:10px;text-transform:uppercase;letter-spacing:1.6px;color:#8194b5;margin:27px 12px 10px}.nav-link{display:block;padding:11px 13px;border-radius:9px;color:#cbd7ea;margin:2px 0;font-size:13px}.nav-link:hover,.nav-link.active{background:#293f65;color:#fff}.sidebar-bottom{margin-top:auto;padding-top:25px}.sidebar .logout{width:100%;background:#263b5c;color:#e7efff}.main{flex:1;min-width:0;padding:34px 40px}.topbar{display:flex;justify-content:space-between;align-items:center;gap:18px;margin-bottom:30px}.topbar h1{font-size:25px;margin-bottom:5px}.profile{display:flex;align-items:center;gap:11px;background:#fff;border:1px solid var(--line);padding:8px 13px;border-radius:12px}.avatar{width:39px;height:39px;border-radius:11px;background:#e9efff;color:#315ee8;display:grid;place-items:center;font-weight:800;font-size:17px}.profile strong{display:block;font-size:12px}.profile small{display:block;color:var(--muted);font-size:11px}.welcome{padding:27px 30px;border-radius:16px;background:linear-gradient(115deg,#142849,#315ee8);color:#fff;margin-bottom:25px;box-shadow:0 14px 35px rgba(36,75,196,.16)}.welcome h2{color:#fff;font-size:23px;margin-bottom:7px}.welcome p{color:#dbe5ff;margin:0;max-width:650px}.welcome .eyebrow{color:#b8cbff}.stats{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:17px;margin:18px 0 25px}.stat{padding:21px}.stat .label{font-size:12px;color:var(--muted);margin-bottom:10px}.stat .value{font:800 27px Manrope,sans-serif;margin-bottom:3px}.stat .note{font-size:11px;color:var(--muted)}.grid-two{display:grid;grid-template-columns:1.3fr 1fr;gap:18px;margin-bottom:20px}.panel h3{font-size:16px;margin-bottom:6px}.panel-head{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:18px}.panel-head p{margin:0;color:var(--muted);font-size:12px}.item{display:flex;justify-content:space-between;align-items:center;gap:14px;padding:15px 0;border-bottom:1px solid #edf0f5}.item:last-child{border:0;padding-bottom:0}.item strong{display:block;font-size:13px}.item small{display:block;color:var(--muted);font-size:11px;margin-top:3px}.quick{display:flex;justify-content:space-between;padding:14px 0;border-bottom:1px solid #edf0f5;font-weight:600;font-size:13px}.quick:last-child{border:0}.details{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:20px}.details small{display:block;color:var(--muted);font-size:11px;margin-bottom:5px}.details strong{font-size:13px;overflow-wrap:anywhere}.table-wrap{overflow-x:auto;border:1px solid var(--line);border-radius:12px;background:#fff}table{width:100%;border-collapse:collapse;min-width:780px}th{background:#f7f9fc;color:#75839a;text-transform:uppercase;letter-spacing:.7px;font-size:10px;text-align:left}th,td{padding:14px 16px;border-bottom:1px solid #edf0f5;vertical-align:top}td{font-size:12px}tr:last-child td{border-bottom:0}.hash{max-width:260px;overflow-wrap:anywhere;font:10px/1.5 monospace;color:#66758e}.page{max-width:1100px;margin:36px auto;padding:0 20px}.page-head{margin-bottom:23px}.page-head h1{font-size:25px;margin:7px 0}.auth-wrap{min-height:100vh;display:grid;grid-template-columns:1fr 1fr;background:#fff}.auth-aside{background:radial-gradient(circle at 20% 15%,#355a9a 0,transparent 32%),linear-gradient(145deg,#101d35,#1c3764);color:#fff;padding:9vw 7vw;display:flex;flex-direction:column;justify-content:space-between}.auth-aside h1{font-size:36px;line-height:1.2;color:#fff;max-width:470px;margin:20px 0}.auth-aside p{color:#c6d5ef;max-width:440px}.auth-mark{font:800 20px Manrope;color:#fff}.auth-mark span{color:#91b0ff}.auth-points{margin-top:45px;color:#d8e4f8}.auth-points div{padding:12px 0;border-top:1px solid #ffffff25}.auth-main{display:grid;place-items:center;padding:45px 25px}.auth-card{width:min(100%,440px)}.auth-card h2{font-size:26px;margin:8px 0}.auth-card .intro{color:var(--muted);margin-bottom:25px}.auth-card .field{margin-bottom:17px}.auth-card button{width:100%;margin-top:5px}.auth-foot{margin-top:22px;text-align:center;color:var(--muted);font-size:12px}.auth-foot a{font-weight:700}.password-row{display:flex;gap:8px}.password-row input{flex:1}.center-card{width:min(100%,520px);margin:8vh auto;padding:34px}.center-card h1{font-size:24px}.center-card .intro{color:var(--muted);margin-bottom:22px}.qr{display:inline-block;padding:16px;background:#fff;border:1px solid var(--line);border-radius:12px;margin:12px 0}.codes{display:grid;grid-template-columns:repeat(2,1fr);gap:8px;padding:0;list-style:none}.codes li{padding:10px;background:#f5f7fb;border:1px solid var(--line);border-radius:7px;font-family:monospace}.footer{text-align:center;color:#9aa6b7;font-size:11px;padding:24px 0}.ticket-form{max-width:760px}.ticket-body{white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.8}.admin-form{min-width:220px}.admin-form label{font-size:11px}.admin-form textarea{min-height:85px}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:18px}
@media(max-width:900px){.auth-wrap{grid-template-columns:1fr}.auth-aside{display:none}.main{padding:25px 20px}.sidebar{width:220px}.grid-two{grid-template-columns:1fr}}
@media(max-width:650px){.shell{display:block}.sidebar{width:100%;padding:18px}.sidebar .nav-caption{margin-top:16px}.sidebar-bottom{padding-top:12px}.main{padding:22px 15px}.topbar{align-items:flex-start;flex-direction:column}.stats{grid-template-columns:1fr}.details{grid-template-columns:1fr}.center-card{margin:20px;padding:23px}.codes{grid-template-columns:1fr}}
</style>
